#!/bin/bash
# The roll-fin valve (Valve_Assembly_v3.usda) on the 90 deg valve-turning task (2026-10-31, user request).
# Harness = the 10-31 v2 runs' (archive/valve_safety_fixes_20261030/sim/chain.sh), the v2 control:
# the v2 bearing (0.072 N.m, drive model), the shipped valve sim yaml (regenerated by try_valve.sh),
# raw mocap, headless, the ARM GS flying Ready / Turn / Exit by itself (--gs-auto), each run stopped 4 s
# after the exit. Only the asset changes: the roll fin FREE (O-ring 2 mN.m) or LOCKED (the screw tight).
#   setsid nohup bash chain.sh <job> [<job> ...] > chain.out 2>&1 &     (touch runs/STOP to skip the rest)
#   job = <free|lock>:<nom|sN>:<tag>      e.g. free:nom:rf_nom_1  lock:s2:rl_s2
C=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/valve_turning_20261015
HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
R="$HERE/../runs"; mkdir -p "$R"
export PL_RUNS_DIR="$R"
export PEGASUS_VALVE_USD=~/fsc_PegasusSimulator/extensions/fsc_aerial_manipulation/fsc_aerial_manipulation/rotorcraft/assets/Valve_Assembly_v3.usda
export PEGASUS_VALVE_FRICTION=0.072 PEGASUS_VALVE_FRICTION_MODEL=drive PEGASUS_VALVE_DAMPING=0.0
export PEGASUS_VALVE_ROTOR_MASS=0        # the asset's masses (226 g rotor + 23 g roll fin)
DRV=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/wb_valve_turning_flight_20261028/tools/driver
clean() { ~/ros2_ws/src/fsc_autopilot_ros2/scripts/isaacsim/stop_isaacsim_stack.sh > /dev/null 2>&1; ~/fsc_PegasusSimulator/scripts/kill_stale_sim_processes.sh -y > /dev/null 2>&1; sleep 5; }
for job in "$@"; do
  [[ -e "$R/STOP" ]] && { echo "STOP file: skipping $job"; continue; }
  IFS=: read -r mode cond tag <<< "$job"
  unset PEGASUS_VALVE_ROLL_LOCK PEGASUS_PLANT_FORCE_NOISE
  [[ $mode == lock ]] && export PEGASUS_VALVE_ROLL_LOCK=1
  [[ $cond == s* ]] && export PEGASUS_PLANT_FORCE_NOISE="0.32,0.12,${cond#s}"
  clean
  echo "$(date +%H:%M:%S) start $tag (roll fin $mode, ${cond}) LOCK=${PEGASUS_VALVE_ROLL_LOCK:-0} NOISE=${PEGASUS_PLANT_FORCE_NOISE:-}"
  { echo "ROLL_MODE=$mode"; echo "ROLL_LOCK=${PEGASUS_VALVE_ROLL_LOCK:-0}"; echo "ROLL_FRICTION=${PEGASUS_VALVE_ROLL_FRICTION:-0.002}";
    echo "VALVE_USD=$PEGASUS_VALVE_USD"; } > "$R/$tag.roll"
  ARM_GS_AUTO_STEPS=true ARM_GS_AUTO_EXIT_DELAY=0.2 RELEASE_AT_OPEN=0 \
    PL_PUSH_TOOLS="$DRV" PL_DRIVER_ARGS="--gs-auto --stop-after-exit --stop-hold 4" bash $C/tools/try_valve.sh "$tag"
done
clean
echo "$(date +%H:%M:%S) CHAIN DONE"
